UPDATE articles a SET body =
  substring(a.body from 1 for position(E'## Частые вопросы' in a.body) - 1)
  || E'Читайте также: ' || v.links || E'\n\n'
  || substring(a.body from position(E'## Частые вопросы' in a.body))
FROM (VALUES
('ai-konsultanty-po-zdorovyu-v-mire', '[Можно ли доверять ИИ-расшифровке анализов](/articles/mozhno-li-doveryat-ii-rasshifrovke-analizov), [Нехватка врачей в мире и в России](/articles/nehvatka-vrachej-prichiny-prognoz) и [Персональная медицина и ИИ](/articles/personalnaya-medicina-i-ii-nablyudenie-za-zdorovem).'),
